 "Cuaderno": "Koadernoa",
 "<b style=\"font-size:25px;color:#5ed3b0\">Cuaderno</b><br><span style=\"font-size:21px;color:#eef1fa\">Para dibujar y anotar.</span>": "<b style=\"font-size:25px;color:#5ed3b0\">Koadernoa</b><br><span style=\"font-size:21px;color:#eef1fa\">Marrazteko eta idazteko.</span>",
 "Plano del cielo": "Zeruaren planoa",
